--= WORKSPACE =--
--=============--
-- Workspace Manager Script
local wksmgr = "~/.config/hypr/scripts/wksmgr.sh"

-- Generate binds automatically from 1 to 9
for i = 0, 9 do
    local key = tostring(i)
    local ws = (i == 0) and 10 or i -- if 0 => then workspace is 10, else it's `i`
	-- Switch workspaces with mainMod + [0-9]
    hl.bind(mainMod, key, hl.dsp.exec_cmd(wksmgr .. " bring " .. ws))
	-- Move active window to a workspace with mainMod + SHIFT + [0-9]
    hl.bind(mainMod .. " SHIFT", key, hl.dsp.window.move({ workspace = ws }))
end

-- Switch workspaces to each other monitor
hl.bind(mainMod .. " SHIFT", "TAB", hl.dsp.exec_cmd(wksmgr .. " switch"))

-- Example special workspace (scratchpad)
-- hl.bind(mainMod, "S", hl.dsp.special_workspace.toggle({ name = "magic" }))
-- hl.bind(mainMod .. " SHIFT", "S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod, "TAB", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " SHIFT", "TAB", hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mainMod, "mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod, "mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod, "mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod, "mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Mover el workspace actual a un monitor específico
hl.bind(mainMod .. " CTRL", "h", hl.dsp.workspace.move_to_monitor({ monitor = "current", workspace = "1" }))
hl.bind(mainMod .. " CTRL", "l", hl.dsp.workspace.move_to_monitor({ monitor = "1" }))

hl.env("HYPRSHOT_DIR", "~/media/images/screenshots")
local screenshot_cmd = [[
    hyprshot --mode region --clipboard-only --raw \
    | satty \
      --filename - \
      --floating-hack \
      --output-filename "${HYPRSHOT_DIR}/%Y-%m-%dT%H:%M:%S.png" \
      --initial-tool brush
]]

-- Bind for screenshots (modifier key is empty "" 'cause doesn't use mainMod)
hl.bind("", "PRINT", hl.dsp.exec_cmd(screenshot_cmd))


